using System.Security.Cryptography;
using CloudinaryDotNet;
using CloudinaryDotNet.Actions;

namespace PropFlow.Modules.RemoteOnlineSign.Infrastructure.Storage;
public sealed record StoredPdf(string Key,string Sha256,long Length);
public interface IRemotePdfStorage { Task<StoredPdf> PutOriginalAsync(Guid contractId, Stream content, long length, CancellationToken ct); Task<StoredPdf> PutDerivedAsync(Guid contractId, string purpose, Stream content, long length, CancellationToken ct); Task<Stream> OpenReadAsync(string key,CancellationToken ct); Task<bool> ExistsWithHashAsync(string key,string hash,CancellationToken ct); Task DeleteIfUnreferencedAsync(string key,CancellationToken ct); }
public sealed class CloudinaryRemotePdfStorage(Cloudinary cloudinary,IHttpClientFactory clients):IRemotePdfStorage
{
 private const long MaxPdfBytes=20*1024*1024;
 public Task<StoredPdf> PutOriginalAsync(Guid contractId,Stream content,long length,CancellationToken ct)=>PutAsync(contractId,"original",content,length,ct);
 public Task<StoredPdf> PutDerivedAsync(Guid contractId,string purpose,Stream content,long length,CancellationToken ct)=>PutAsync(contractId,purpose,content,length,ct);
 private async Task<StoredPdf> PutAsync(Guid contractId,string purpose,Stream content,long length,CancellationToken ct){if(length is <=0 or >MaxPdfBytes)throw new ArgumentException("PDF phải có kích thước tối đa 20 MB.");if(string.IsNullOrWhiteSpace(purpose)||purpose.Any(x=>!(char.IsAsciiLetterOrDigit(x)||x=='-')))throw new ArgumentException("Loại PDF không hợp lệ.");await using var copy=new MemoryStream();await content.CopyToAsync(copy,ct);var bytes=copy.ToArray();if(bytes.Length!=length)throw new ArgumentException("Kích thước PDF không hợp lệ.");var hash=Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();var key=$"propflow/remote-online-sign/contracts/{contractId:N}/{purpose}/{Guid.NewGuid():N}";await using var input=new MemoryStream(bytes,false);var result=await cloudinary.UploadAsync(new RawUploadParams{File=new FileDescription("contract.pdf",input),PublicId=key,Overwrite=false,UseFilename=false,UniqueFilename=false,Type="authenticated",Tags="remote-online-sign"},"pdf",ct).WaitAsync(TimeSpan.FromSeconds(60),ct);if(result.Error is not null||string.IsNullOrWhiteSpace(result.PublicId))throw new IOException("Không thể lưu PDF hợp đồng.");return new(result.PublicId,hash,bytes.LongLength);}
 public async Task<Stream> OpenReadAsync(string key,CancellationToken ct){var expiresAt=DateTimeOffset.UtcNow.AddMinutes(5).ToUnixTimeSeconds();var url=cloudinary.DownloadPrivate(key,false,null,"authenticated",expiresAt,"raw");const int maxAttempts=2;for(var attempt=1;;attempt++){try{using var response=await clients.CreateClient("RemoteContractCloudinary").GetAsync(url,HttpCompletionOption.ResponseHeadersRead,ct);if((int)response.StatusCode>=500&&attempt<maxAttempts){await Task.Delay(400*attempt,ct);continue;}if(!response.IsSuccessStatusCode)throw new FileNotFoundException("Không tìm thấy PDF hợp đồng.");var result=new MemoryStream();await using var source=await response.Content.ReadAsStreamAsync(ct);await source.CopyToAsync(result,ct);result.Position=0;return result;}catch(Exception e)when(attempt<maxAttempts&&IsTransient(e,ct)){await Task.Delay(400*attempt,ct);}}static bool IsTransient(Exception e,CancellationToken ct)=>(e is not FileNotFoundException)&&((e is TaskCanceledException or TimeoutException)&&!ct.IsCancellationRequested||e is HttpRequestException);}
 public async Task<bool> ExistsWithHashAsync(string key,string hash,CancellationToken ct){try{await using var input=await OpenReadAsync(key,ct);return string.Equals(Convert.ToHexString(await SHA256.HashDataAsync(input,ct)).ToLowerInvariant(),hash,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 public async Task DeleteIfUnreferencedAsync(string key,CancellationToken ct){var result=await cloudinary.DestroyAsync(new DeletionParams(key){ResourceType=ResourceType.Raw,Type="authenticated",Invalidate=true}).WaitAsync(TimeSpan.FromSeconds(30),ct);if(result.Error is not null)throw new IOException("Không thể cleanup PDF chưa tham chiếu.");}
}
